//! The command-line reference (`docs/reference/cli.md`, `isoloom docs --cli`): every command and
//! its arguments, written from the command line's own definition, so the page can't drift from
//! `--help`.

use clap::{Arg, ArgAction, Command, CommandFactory};

use crate::cli::Cli;

/// The page.
pub(crate) fn markdown() -> String {
    let mut root = Cli::command();
    root.build();
    let head = format!(
        "# Command-line reference\n\n<!-- Generated by `isoloom docs --cli` from the command line's definition: don't edit. -->\n\n{}\n\n{}",
        about(&root),
        options("Global options", root.get_arguments().filter(|a| a.is_global_set()))
    );
    std::iter::once(head).chain(root.get_subcommands().map(section)).collect::<Vec<_>>().concat()
}

/// A command's section, then its subcommands'.
fn section(command: &Command) -> String {
    let name = command.get_bin_name().unwrap_or_else(|| command.get_name());
    let usage = command.clone().render_usage().to_string();
    let own = format!(
        "## `{name}`\n\n{}\n\n```text\n{}\n```\n\n{}",
        about(command),
        usage.trim(),
        options("Arguments", command.get_arguments().filter(|a| !a.is_global_set()))
    );
    std::iter::once(own).chain(command.get_subcommands().map(section)).collect::<Vec<_>>().concat()
}

/// What a command does: its long description, else its short one.
fn about(command: &Command) -> String {
    sentence(
        &command
            .get_long_about()
            .or_else(|| command.get_about())
            .map(ToString::to_string)
            .unwrap_or_default(),
    )
}

/// `text` on one line, ending as a sentence does (clap drops a doc comment's final period).
fn sentence(text: &str) -> String {
    let line = text.split_whitespace().collect::<Vec<_>>().join(" ");
    if line.is_empty() || line.ends_with(['.', '?', '!', ':']) {
        line
    } else {
        format!("{line}.")
    }
}

/// A table of `args`, under `title` (nothing when there are none to show).
fn options<'a>(title: &str, args: impl Iterator<Item = &'a Arg>) -> String {
    let rows: Vec<String> = args.filter(|a| shown(a)).map(row).collect();
    if rows.is_empty() {
        return String::new();
    }
    format!("{title}:\n\n| Argument | Description |\n| --- | --- |\n{}\n", rows.concat())
}

/// Whether the reference lists `a`: not clap's own `--help` and `--version`, nor a hidden one.
fn shown(a: &Arg) -> bool {
    !a.is_hide_set() && !matches!(a.get_action(), ArgAction::Help | ArgAction::HelpLong | ArgAction::Version)
}

/// `a`'s row: how it is written, then what it does, its choices and its default.
fn row(a: &Arg) -> String {
    let help = a.get_long_help().or_else(|| a.get_help()).map(ToString::to_string).unwrap_or_default();
    let choices: Vec<String> = a
        .get_possible_values()
        .iter()
        .filter(|v| !v.is_hide_set())
        .map(|v| format!("`{}`", v.get_name()))
        .collect();
    let defaults: Vec<String> = a.get_default_values().iter().map(|v| v.to_string_lossy().into_owned()).collect();
    let mut parts = vec![sentence(&help)];
    if takes_value(a) && !choices.is_empty() {
        parts.push(format!("One of {}.", choices.join(", ")));
    }
    if takes_value(a) && !defaults.is_empty() {
        parts.push(format!("Default: `{}`.", defaults.join(" ")));
    }
    let text = parts.into_iter().filter(|p| !p.is_empty()).collect::<Vec<_>>().join(" ");
    format!("| `{}` | {} |\n", written(a), text.replace('|', "\\|"))
}

/// Whether `a` takes a value (a flag doesn't).
fn takes_value(a: &Arg) -> bool {
    matches!(a.get_action(), ArgAction::Set | ArgAction::Append)
}

/// How `a` is written on the command line: `-s, --set <KEY=VALUE>`, `--json`, `[DIR]`.
fn written(a: &Arg) -> String {
    let value = a.get_value_names().map_or_else(
        || format!("<{}>", a.get_id().as_str().to_uppercase()),
        |names| names.iter().map(|n| format!("<{n}>")).collect::<Vec<_>>().join(" "),
    );
    if a.is_positional() {
        let bare = value.trim_start_matches('<').trim_end_matches('>');
        return if a.is_required_set() { format!("<{bare}>") } else { format!("[{bare}]") };
    }
    let mut names: Vec<String> = a.get_short().map(|s| format!("-{s}")).into_iter().collect();
    names.extend(a.get_long().map(|l| format!("--{l}")));
    let names = names.join(", ");
    if takes_value(a) { format!("{names} {value}") } else { names }
}
